(function(root){
 'use strict';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const ER=typeof module!=='undefined'?require('./engine.js'):root.ER;
 const zooms=new Map();
 function layout(c,s){
  const catalog=[...c.entities,...c.distractors],ids=new Set(s.entities),links=[];
  if(s.step>=2&&s.associationsConfirmed)for(const r of c.relations.filter(r=>s.associationChoices.includes(r.id))){const v=s.relations[r.id];if(v&&catalog.some(e=>e.id===v.from)&&catalog.some(e=>e.id===v.to)){ids.add(v.from);ids.add(v.to);links.push({id:r.id,r,v,from:v.from,to:v.to,notation:ER.diagramRelation(r,v)});}}
  const nodes=catalog.filter(e=>ids.has(e.id)).map(e=>({id:e.id,name:e.name,weak:s.identifications?.[e.id]?.kind==='dependent',attrs:s.attrs[e.id]||[],keys:s.keys[e.id]||[],w:240,h:Math.max(98,58+26*(s.attrs[e.id]?.length||1)),x:0,y:0}));
  const byId=new Map(nodes.map(n=>[n.id,n])),adj=new Map(nodes.map(n=>[n.id,new Set()]));
  for(const e of links)if(e.from!==e.to){adj.get(e.from).add(e.to);adj.get(e.to).add(e.from);}
  const remaining=new Set(nodes.map(n=>n.id));let offsetY=36,width=312;const edges=[];
  while(remaining.size){
   const seed=[...remaining].sort((a,b)=>adj.get(b).size-adj.get(a).size)[0],queue=[seed],ranks=new Map([[seed,0]]),parent=new Map();remaining.delete(seed);
   for(let i=0;i<queue.length;i++)for(const id of adj.get(queue[i]))if(remaining.has(id)){remaining.delete(id);parent.set(id,queue[i]);ranks.set(id,ranks.get(queue[i])+1);queue.push(id);}
   const layers=[];for(const id of queue)(layers[ranks.get(id)]||=[]).push(byId.get(id));
   const componentWidth=Math.max(...layers.map(l=>l.length*320-80))+72;let y=offsetY;
   for(const layer of layers){const rowWidth=layer.length*320-80;layer.forEach((n,i)=>{n.x=(componentWidth-rowWidth)/2+i*320;n.y=y;});y+=Math.max(...layer.map(n=>n.h))+184;}
   const componentLinks=links.filter(e=>ranks.has(e.from)),seenPairs=new Set();let lane=0;
   for(const e of componentLinks){const a=byId.get(e.from),b=byId.get(e.to),pair=[e.from,e.to].sort().join('|');const tree=e.from!==e.to&&!seenPairs.has(pair)&&(parent.get(e.from)===e.to||parent.get(e.to)===e.from);seenPairs.add(pair);
    const label={w:Math.max(148,e.r.verb.length*9+48),h:e.r.attr?60:38};let pa,pb,pathA,pathB;
    if(tree){const upper=a.y<b.y?a:b,lower=a.y<b.y?b:a;const children=queue.filter(id=>parent.get(id)===upper.id).map(id=>byId.get(id)).sort((x,y)=>x.x-y.x);const index=children.findIndex(n=>n.id===lower.id);const up={x:upper.x+upper.w*(index+1)/(children.length+1),y:upper.y+upper.h},down={x:lower.x+lower.w/2,y:lower.y};label.x=down.x-label.w/2;label.y=(up.y+down.y-label.h)/2;const upperPath=[up,{x:label.x+label.w/2,y:label.y}],lowerPath=[down,{x:label.x+label.w/2,y:label.y+label.h}];pa=a===upper?up:down;pb=b===upper?up:down;pathA=a===upper?upperPath:lowerPath;pathB=b===upper?upperPath:lowerPath;
    }else{ // Separate ports and an exterior lane for recursive / extra edges.
     const loop=a===b,outerX=componentWidth+48+lane*210;label.x=outerX;label.y=loop?a.y+a.h/2-label.h/2:(a.y+b.y+a.h/2+b.h/2)/2-label.h/2;
     pa=loop?{x:a.x+a.w,y:a.y+25}:{x:a.x+a.w/2,y:a.y};pb=loop?{x:b.x+b.w,y:b.y+b.h-25}:{x:b.x+b.w/2,y:b.y+b.h};
     const cx=label.x+label.w/2;
     pathA=loop?[pa,{x:cx,y:pa.y},{x:cx,y:label.y}]:[pa,{x:pa.x,y:a.y-24},{x:cx,y:a.y-24},{x:cx,y:label.y}];
     pathB=loop?[pb,{x:cx,y:pb.y},{x:cx,y:label.y+label.h}]:[pb,{x:pb.x,y:b.y+b.h+24},{x:cx,y:b.y+b.h+24},{x:cx,y:label.y+label.h}];lane++;
    }
    const canonicalForward=e.from===e.r.from&&e.to===e.r.to;const canonicalReverse=e.r.from!==e.r.to&&e.from===e.r.to&&e.to===e.r.from;let direction='';if(canonicalForward||canonicalReverse){const from=canonicalReverse?pb:pa,to=canonicalReverse?pa:pb;direction=from.y<=to.y?'▼':'▲';}
    const card=(p,n,points)=>{const dy=points[1].y-p.y,dx=points[1].x-p.x;return {x:p.x+(Math.abs(dy)<1?16:12),y:p.y+(Math.abs(dy)<1?-9:dy>0?21:-11),text:n};};
    edges.push({...e,label,pa,pb,pathA,pathB,direction,cardA:card(pa,e.notation.top,pathA),cardB:card(pb,e.notation.bottom,pathB)});width=Math.max(width,label.x+label.w+36);
   }
   width=Math.max(width,componentWidth);offsetY=y-184+70;
  }
  return {nodes,edges,width,height:Math.max(150,offsetY),pending:s.step>=2&&s.associationsConfirmed?c.relations.filter(r=>s.associationChoices.includes(r.id)).length-links.length:0};
 }
 function svg(c,s,g){
  const description=g.edges.map(e=>`${e.v.from} ${e.r.verb} ${e.v.to}. Prima entità: cardinalità ${e.notation.top||'non scelta'}, partecipazione ${e.notation.partA==='required'?'obbligatoria':e.notation.partA==='optional'?'facoltativa':'non scelta'}. Seconda entità: cardinalità ${e.notation.bottom||'non scelta'}, partecipazione ${e.notation.partB==='required'?'obbligatoria':e.notation.partB==='optional'?'facoltativa':'non scelta'}.`).join(' ');
  const path=(points,part)=>`<path d="${points.map((p,i)=>`${i?'L':'M'}${p.x},${p.y}`).join(' ')}" class="graph-line ${part}"/>`;
  return `<svg class="graph-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${g.width} ${g.height}" role="img" aria-label="Modello E/R: ${g.nodes.length} entità e ${g.edges.length} ${g.edges.length===1?'associazione':'associazioni'}"><title>Modello E/R costruito con le tue scelte</title><desc>${esc(description)}</desc>${g.edges.map(e=>`<g class="graph-association" data-association="${esc(e.id)}">${path(e.pathA,e.notation.partA)}${path(e.pathB,e.notation.partB)}<g class="graph-cardinality"><text x="${e.cardA.x}" y="${e.cardA.y}">${esc(e.cardA.text)}</text><text x="${e.cardB.x}" y="${e.cardB.y}">${esc(e.cardB.text)}</text></g><rect x="${e.label.x}" y="${e.label.y}" width="${e.label.w}" height="${e.label.h}" rx="7" class="graph-association-box"/><text x="${e.label.x+e.label.w/2}" y="${e.label.y+24}" text-anchor="middle" class="graph-verb">${esc(e.r.verb)} ${e.direction}</text>${e.r.attr?`<text x="${e.label.x+e.label.w/2}" y="${e.label.y+47}" text-anchor="middle" class="graph-association-attr">${esc(e.r.attr)}</text>`:''}${e.from===e.to?`<text x="${e.pa.x+12}" y="${e.pa.y-24}" class="graph-role">composta</text><text x="${e.pb.x+12}" y="${e.pb.y+27}" class="graph-role">componente</text>`:''}</g>`).join('')}${g.nodes.map(n=>`<g class="graph-entity" data-entity="${esc(n.id)}"><title>${esc(n.name)}</title>${n.weak?`<rect x="${n.x-5}" y="${n.y-5}" width="${n.w+10}" height="${n.h+10}" rx="9" class="graph-weak"/>`:''}<rect x="${n.x}" y="${n.y}" width="${n.w}" height="${n.h}" rx="5" class="graph-entity-box"/><path d="M${n.x},${n.y+40}H${n.x+n.w}" class="graph-divider"/><text x="${n.x+n.w/2}" y="${n.y+26}" text-anchor="middle" class="graph-entity-title">${esc(n.name)}</text>${n.attrs.length?n.attrs.map((a,i)=>`<text x="${n.x+14}" y="${n.y+65+i*26}" class="graph-field">${esc(a)}</text>${n.keys.includes(a)?`<text x="${n.x+n.w-14}" y="${n.y+65+i*26}" text-anchor="end" class="graph-key">PK</text>`:''}`).join(''):`<text x="${n.x+14}" y="${n.y+67}" class="graph-placeholder">Attributi da definire</text>`}</g>`).join('')}</svg>`;
 }
 function render(c,s){const g=layout(c,s);if(!g.nodes.length)return '';const zoom=zooms.get(c.id)||'fit';return `<div class="er-graph" data-graph="${esc(c.id)}" data-width="${g.width}" data-height="${g.height}"><div class="diagram-tools" role="group" aria-label="Vista del diagramma"><button type="button" data-diagram="fit">Adatta</button><button type="button" data-diagram="out" aria-label="Riduci diagramma">−</button><span class="diagram-scale" aria-live="polite">${zoom==='fit'?'Adattato':Math.round(zoom*100)+'%'}</span><button type="button" data-diagram="in" aria-label="Ingrandisci diagramma">+</button><button type="button" data-diagram="expand">Vista ampia</button></div><div class="diagram-viewport" tabindex="0" role="region" aria-label="Diagramma E/R navigabile: usa lo zoom e scorri per esplorarlo"><div class="diagram-surface" style="width:${zoom==='fit'?`min(100%, calc(var(--graph-fit-height, 520px) * ${g.width/g.height}))`:g.width*zoom+'px'}">${svg(c,s,g)}</div></div><p class="diagram-note">${g.nodes.length} entità · ${g.edges.length} ${g.edges.length===1?'associazione':'associazioni'}${g.pending?` · ${g.pending} da collegare`:''}. Usa + per leggere i dettagli; scorri per spostarti.</p></div>`;}
 const API={layout,render};if(typeof module!=='undefined')module.exports=API;root.ERGraph=API;
 if(typeof document!=='undefined')document.addEventListener('click',event=>{const button=event.target.closest('[data-diagram]');if(!button)return;const action=button.dataset.diagram;if(action==='close'){button.closest('dialog').close();return;}const graph=button.closest('.er-graph'),surface=graph.querySelector('.diagram-surface'),viewport=graph.querySelector('.diagram-viewport'),nativeWidth=Number(graph.dataset.width),key=graph.dataset.graph;
  if(action==='expand'){const dialog=document.createElement('dialog');dialog.className='diagram-dialog';dialog.setAttribute('aria-label','Vista ampia del modello E/R');dialog.innerHTML='<div class="diagram-dialog-head"><h2>Il tuo modello E/R</h2><button data-diagram="close" autofocus>Chiudi</button></div>';const copy=graph.cloneNode(true);copy.querySelector('[data-diagram="expand"]').remove();copy.querySelector('.diagram-surface').style.width=`min(100%, calc(var(--graph-fit-height, 520px) * ${Number(copy.dataset.width)/Number(copy.dataset.height)}))`;copy.querySelector('.diagram-scale').textContent='Adattato';dialog.append(copy);document.body.append(dialog);dialog.addEventListener('close',()=>{dialog.remove();button.focus();});dialog.showModal();return;}
  const current=surface.getBoundingClientRect().width/nativeWidth;const next=action==='fit'?'fit':Math.max(.3,Math.min(2.5,action==='in'?Math.max(1,current*1.35):current/1.35));const centerX=(viewport.scrollLeft+viewport.clientWidth/2)/surface.getBoundingClientRect().width,centerY=(viewport.scrollTop+viewport.clientHeight/2)/surface.getBoundingClientRect().height;
  surface.style.width=next==='fit'?`min(100%, calc(var(--graph-fit-height, 520px) * ${nativeWidth/Number(graph.dataset.height)}))`:nativeWidth*next+'px';graph.querySelector('.diagram-scale').textContent=next==='fit'?'Adattato':Math.round(next*100)+'%';if(!graph.closest('dialog'))zooms.set(key,next);viewport.scrollLeft=centerX*surface.getBoundingClientRect().width-viewport.clientWidth/2;viewport.scrollTop=centerY*surface.getBoundingClientRect().height-viewport.clientHeight/2;
 });
})(typeof window!=='undefined'?window:globalThis);
